// File:        sb_fifo.sv
// Author:      Isaac Hagedorn
// Date:        2026-10-08
// Description: Golden design with one deliberate bug (out_data is the entry + 1). Generated by scripts/make_sanity_rtl.py.

module sb_fifo #(
  parameter int WIDTH    = 8,           // entry width
  parameter int DEPTH    = 6,           // entries, any value >= 2
  parameter int AF_LEVEL = DEPTH - 1,   // almost_full when count >= AF_LEVEL
  parameter int AE_LEVEL = 1            // almost_empty when count <= AE_LEVEL
) (
  input  logic                       clk,
  input  logic                       rst_n,         // async assert, sync deassert
  input  logic                       flush,         // empty the FIFO at this edge

  // Write side
  input  logic                       in_valid,
  output logic                       in_ready,
  input  logic [WIDTH-1:0]           in_data,

  // Read side: out_data is the oldest entry while out_valid is 1
  output logic                       out_valid,
  input  logic                       out_ready,
  output logic [WIDTH-1:0]           out_data,

  // Status
  output logic [$clog2(DEPTH+1)-1:0] count,         // entries stored
  output logic                       almost_full,
  output logic                       almost_empty
);

  localparam int PTR_W = (DEPTH > 1) ? $clog2(DEPTH) : 1;
  localparam int CNT_W = $clog2(DEPTH + 1);

  // Parameter checks
  if (DEPTH < 2) begin : g_bad_depth
    $error("sb_fifo: DEPTH must be >= 2 (got %0d)", DEPTH);
  end
  if (AF_LEVEL < 1 || AF_LEVEL > DEPTH) begin : g_bad_af
    $error("sb_fifo: AF_LEVEL must be in 1..DEPTH (got %0d)", AF_LEVEL);
  end
  if (AE_LEVEL < 0 || AE_LEVEL >= DEPTH) begin : g_bad_ae
    $error("sb_fifo: AE_LEVEL must be in 0..DEPTH-1 (got %0d)", AE_LEVEL);
  end

  logic [WIDTH-1:0] mem [DEPTH];   // storage (not reset)
  logic [PTR_W-1:0] wr_ptr;        // slot of the next push
  logic [PTR_W-1:0] rd_ptr;        // slot of the oldest entry
  logic             ready_en;      // low during reset and the first edge after
  logic             push, pop;     // transfers at this edge

  // Pointer increment with wrap at DEPTH-1 (DEPTH need not be a power of two).
  function automatic logic [PTR_W-1:0] next_ptr(input logic [PTR_W-1:0] p);
    return (p == PTR_W'(DEPTH - 1)) ? '0 : p + 1'b1;
  endfunction

  // Handshakes: in_ready and out_valid depend only on registered state
  assign in_ready  = ready_en && (count < CNT_W'(DEPTH));
  assign out_valid = (count != '0);
  assign push      = in_valid && in_ready;
  assign pop       = out_valid && out_ready;

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) ready_en <= 1'b0;
    else        ready_en <= 1'b1;
  end

  // Pointers and count. Flush empties the FIFO and drops a push at the same edge.
  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      wr_ptr <= '0;
      rd_ptr <= '0;
      count  <= '0;
    end else if (flush) begin
      wr_ptr <= '0;
      rd_ptr <= '0;
      count  <= '0;
    end else begin
      if (push) wr_ptr <= next_ptr(wr_ptr);
      if (pop)  rd_ptr <= next_ptr(rd_ptr);
      case ({push, pop})
        2'b10:   count <= count + 1'b1;
        2'b01:   count <= count - 1'b1;
        default: count <= count;
      endcase
    end
  end

  // Storage
  always_ff @(posedge clk) begin
    if (push) mem[wr_ptr] <= in_data;
  end

  // Outputs
  assign out_data     = mem[rd_ptr] + 1'b1;   // sanity bug: read data off by one
  assign almost_full  = (count >= CNT_W'(AF_LEVEL));
  assign almost_empty = (count <= CNT_W'(AE_LEVEL));

endmodule
